









local startup_template={}


local RECOVERY_LINES={
"-- Undo a half-done or unconfirmed over-the-air update before anything else is loaded.",
'local ok_recovery, recovery = pcall(require, "src.shared.ota_recovery")',
"if ok_recovery then",
"  local ran, action, detail = pcall(recovery.recover)",
'  if ran and action ~= "none" then print("OTA recovery: " .. tostring(action) .. " " .. tostring(detail or "")) end',
"end",
"",
}



local INSTALL_GUARD_LINES={
"-- An interrupted installation is finished before the role starts.",
'if fs.exists("crn_install_journal.lua") or fs.exists("crn_install_journal.lua.prev") then',
'  print("Installation unvollstaendig.")',
'  if fs.exists("installer") and shell then',
'    print("Setze sie fort: installer --resume")',
'    shell.run("installer", "--resume")',
"  else",
'    print("Bitte den Installer erneut ausfuehren (wget run <url>/installer).")',
"  end",
"  return",
"end",
"",
}

local ROLES={"master","signal","sensor","switch","train","station","depot","panel","arbiter","fleet"}

local function is_role(role)
for _,r in ipairs(ROLES)do if r==role then return true end end
return false
end

function startup_template.render(opts)
local o=opts or{}
if not is_role(o.role)then return nil,"unknown role: " .. tostring(o.role)end
if type(o.id)~="string" or not o.id:match("^[%w_%-%.]+$")then return nil,"node id may only contain letters, digits, _ - ." end
if type(o.config)~="string" or o.config=="" then return nil,"config path is missing" end

local lines={
"-- CreateRailNet-V3 auto-generated by setup.lua",
"-- Role: " .. o.role .. "  ID: " .. o.id,
'-- To reconfigure: delete this file and run: shell.run("scripts/setup.lua")',
"",
"local CRN_ROLE   = " .. string.format("%q",o.role),
"local CRN_ID     = " .. string.format("%q",o.id),
"local CRN_CONFIG = " .. string.format("%q",o.config),
"",
"local role_entrypoints = {",
'  master  = "src.master.main",',
'  signal  = "src.nodes.signal_node",',
'  sensor  = "src.nodes.sensor_node",',
'  switch  = "src.nodes.switch_node",',
'  train   = "src.nodes.train_node",',
'  station = "src.nodes.station_node",',
'  depot   = "src.nodes.depot_node",',
'  arbiter = "src.nodes.arbiter_node",',
'  fleet   = "src.nodes.fleet_node",',
'  panel   = "src.nodes.panel_node",',
"}",
"",
"local entrypoint = role_entrypoints[CRN_ROLE]",
'if not entrypoint then error("Unknown CRN_ROLE: " .. tostring(CRN_ROLE)) end',
"",
"local function read_version()",
'  if fs and fs.exists and fs.exists("crn_version.txt") then',
'    local fh = fs.open("crn_version.txt", "r")',
'    if fh then local v = fh.readLine(); fh.close(); return v end',
"  end",
'  return "unknown"',
"end",
"",
'print("CreateRailNet v" .. read_version() .. "  role=" .. CRN_ROLE .. "  id=" .. CRN_ID)',
"",
"local mod = require(entrypoint)",
"if mod and mod.new_runtime then",
"  mod.new_runtime({ id = CRN_ID, config = CRN_CONFIG }).run()",
"elseif mod and mod.run then",
"  mod.run({ id = CRN_ID, config = CRN_CONFIG })",
"else",
'  shell.run("run", entrypoint, "--id", CRN_ID, "--config", CRN_CONFIG)',
"end",
}
local out={}
for _,line in ipairs(lines)do
if line=="local entrypoint = role_entrypoints[CRN_ROLE]" then
for _,recovery_line in ipairs(RECOVERY_LINES)do out[#out+1]=recovery_line end
for _,guard_line in ipairs(INSTALL_GUARD_LINES)do out[#out+1]=guard_line end
end
out[#out+1]=line
end
return table.concat(out,"\n").. "\n"
end




function startup_template.upgrade(text)
if type(text)~="string" then return nil,"no startup.lua text" end
local missing={}
if not text:find("src.shared.ota_recovery",1,true)then for _,line in ipairs(RECOVERY_LINES)do missing[#missing+1]=line end end
if not text:find("crn_install_journal",1,true)then for _,line in ipairs(INSTALL_GUARD_LINES)do missing[#missing+1]=line end end
if#missing==0 then return text,"current" end
local anchor="local entrypoint = role_entrypoints[CRN_ROLE]"
local first=text:find(anchor,1,true)
if not first then return nil,"layout not recognised (no '" .. anchor .. "' line)" end
if text:find(anchor,first+1,true)then return nil,"layout not recognised (entry point line twice)" end
local upgraded=text:sub(1,first - 1).. table.concat(missing,"\n").. "\n" .. text:sub(first)
local compile=loadstring or load
local chunk,err=compile(upgraded,"startup.lua")
if not chunk then return nil,"upgrade would not load: " .. tostring(err)end
return upgraded,"upgraded"
end


function startup_template.parse(text)
if type(text)~="string" then return nil end
local role=text:match('local CRN_ROLE%s*=%s*"([^"\n]*)"')
local id=text:match('local CRN_ID%s*=%s*"([^"\n]*)"')
local config=text:match('local CRN_CONFIG%s*=%s*"([^"\n]*)"')
if not(role and id and config)then return nil end
return{role=role,id=id,config=config}
end

startup_template.ROLES=ROLES

return startup_template
